function stageOf6(c) {
  return c === "infiltrate" ? 0 : c === "rewrite" ? 1 : 2;
}
function activityOf6(p) {
  return p?.activity?.phase === "rest" ? 0 : p?.activity?.phase === "waking" ? p.activity.progress : 1;
}
function putPixel6(out, w, h, x, y, ink, alpha = 255) {
  x = Math.round(x);
  y = Math.round(y);
  if (x < 0 || y < 0 || x >= w || y >= h) return;
  const i = (y * w + x) * 4;
  out[i] = ink[0];
  out[i + 1] = ink[1];
  out[i + 2] = ink[2];
  out[i + 3] = alpha;
}
